-- Load the synthetic bank generated by scripts/bank_data/generate.py.
-- Run from the repo root (psql >= 14), with the connection string in an env var:
--
--   python3 scripts/bank_data/generate.py
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/bank_data/load.sql
--
-- One transaction, re-runnable: the generated tables are truncated first.
-- The catalogue (ecosystems, partners, ecosystem_items) is only read, never written:
-- CSVs carry the Excel row (`ecosystem_item_row`), resolved here through source_row.

\set ON_ERROR_STOP on
begin;

truncate public.app_events, public.transactions, public.product_holdings, public.loans, public.accounts,
         public.properties, public.customer_housing, public.customer_employment, public.customer_children,
         ml.customer_truth, public.customers;

\copy public.customers (id, first_name, last_name, birth_date, gender, language, email, postal_code, city, region, marital_status, segment, customer_since, is_demo, demo_slug) from 'scripts/bank_data/out/customers.csv' with (format csv, header true)
\copy public.customer_children (id, customer_id, first_name, birth_date) from 'scripts/bank_data/out/customer_children.csv' with (format csv, header true)
\copy public.customer_employment (customer_id, status, sector, employer_name, company_name, company_vat, company_founded_on, monthly_net_income_eur, since) from 'scripts/bank_data/out/customer_employment.csv' with (format csv, header true)
\copy public.customer_housing (customer_id, status, monthly_rent_eur) from 'scripts/bank_data/out/customer_housing.csv' with (format csv, header true)
\copy public.properties (id, customer_id, kind, build_year, epc_label, estimated_value_eur, postal_code, acquired_on) from 'scripts/bank_data/out/properties.csv' with (format csv, header true)
\copy ml.customer_truth (customer_id, persona, life_moment, moment_started_on, converted) from 'scripts/bank_data/out/customer_truth.csv' with (format csv, header true)

-- Tables that reference the catalogue go through a staging table.
create temp table stage_accounts (id bigint, customer_id bigint, ecosystem_item_row int, kind text, iban text,
  opened_on date, balance_eur numeric) on commit drop;
create temp table stage_loans (id bigint, customer_id bigint, ecosystem_item_row int, kind text, principal_eur numeric,
  annual_rate_pct numeric, term_months int, monthly_payment_eur numeric, start_date date, end_date date,
  outstanding_eur numeric, status text) on commit drop;
create temp table stage_holdings (id bigint, customer_id bigint, ecosystem_item_row int, since date,
  monthly_premium_eur numeric, status text) on commit drop;
create temp table stage_events (id bigint, customer_id bigint, session_id text, occurred_at timestamptz, channel text,
  event_type text, ecosystem_item_row int, detail jsonb) on commit drop;

\copy stage_accounts from 'scripts/bank_data/out/accounts.csv' with (format csv, header true)
\copy stage_loans from 'scripts/bank_data/out/loans.csv' with (format csv, header true)
\copy stage_holdings from 'scripts/bank_data/out/product_holdings.csv' with (format csv, header true)
\copy stage_events from 'scripts/bank_data/out/app_events.csv' with (format csv, header true)

insert into public.accounts (id, customer_id, ecosystem_item_id, kind, iban, opened_on, balance_eur)
select s.id, s.customer_id, ei.id, s.kind, s.iban, s.opened_on, s.balance_eur
from stage_accounts s left join public.ecosystem_items ei on ei.source_row = s.ecosystem_item_row;

insert into public.loans (id, customer_id, ecosystem_item_id, kind, principal_eur, annual_rate_pct, term_months,
  monthly_payment_eur, start_date, end_date, outstanding_eur, status)
select s.id, s.customer_id, ei.id, s.kind, s.principal_eur, s.annual_rate_pct, s.term_months, s.monthly_payment_eur,
  s.start_date, s.end_date, s.outstanding_eur, s.status
from stage_loans s left join public.ecosystem_items ei on ei.source_row = s.ecosystem_item_row;

insert into public.product_holdings (id, customer_id, ecosystem_item_id, since, monthly_premium_eur, status)
select s.id, s.customer_id, ei.id, s.since, s.monthly_premium_eur, s.status
from stage_holdings s join public.ecosystem_items ei on ei.source_row = s.ecosystem_item_row;

\copy public.transactions (id, account_id, customer_id, booked_on, amount_eur, category, counterparty, description) from 'scripts/bank_data/out/transactions.csv' with (format csv, header true)

insert into public.app_events (id, customer_id, session_id, occurred_at, channel, event_type, ecosystem_item_id, detail)
select s.id, s.customer_id, s.session_id, s.occurred_at, s.channel, s.event_type, ei.id, s.detail
from stage_events s left join public.ecosystem_items ei on ei.source_row = s.ecosystem_item_row;

-- Fail loudly if a catalogue row could not be resolved (instead of silently loading nulls).
do $$
declare missing int;
begin
  select (select count(*) from stage_accounts s where s.ecosystem_item_row is not null
            and not exists (select 1 from public.ecosystem_items ei where ei.source_row = s.ecosystem_item_row))
       + (select count(*) from stage_loans s where s.ecosystem_item_row is not null
            and not exists (select 1 from public.ecosystem_items ei where ei.source_row = s.ecosystem_item_row))
       + (select count(*) from stage_holdings s
            where not exists (select 1 from public.ecosystem_items ei where ei.source_row = s.ecosystem_item_row))
       + (select count(*) from stage_events s where s.ecosystem_item_row is not null
            and not exists (select 1 from public.ecosystem_items ei where ei.source_row = s.ecosystem_item_row))
    into missing;
  if missing > 0 then
    raise exception 'catalogue rows not found for % generated rows: load the catalogue first', missing;
  end if;
end $$;

-- Keep identity sequences ahead of the explicit ids.
select setval(pg_get_serial_sequence('public.customers', 'id'), coalesce((select max(id) from public.customers), 1));
select setval(pg_get_serial_sequence('public.customer_children', 'id'), coalesce((select max(id) from public.customer_children), 1));
select setval(pg_get_serial_sequence('public.properties', 'id'), coalesce((select max(id) from public.properties), 1));
select setval(pg_get_serial_sequence('public.accounts', 'id'), coalesce((select max(id) from public.accounts), 1));
select setval(pg_get_serial_sequence('public.loans', 'id'), coalesce((select max(id) from public.loans), 1));
select setval(pg_get_serial_sequence('public.product_holdings', 'id'), coalesce((select max(id) from public.product_holdings), 1));
select setval(pg_get_serial_sequence('public.transactions', 'id'), coalesce((select max(id) from public.transactions), 1));
select setval(pg_get_serial_sequence('public.app_events', 'id'), coalesce((select max(id) from public.app_events), 1));

commit;

analyze public.customers, public.transactions, public.app_events, public.accounts, public.loans, public.product_holdings;

select 'customers' as table_name, count(*) from public.customers
union all select 'transactions', count(*) from public.transactions
union all select 'app_events', count(*) from public.app_events
union all select 'product_holdings', count(*) from public.product_holdings
union all select 'customer_truth', count(*) from ml.customer_truth;
